const items = $input.all();
const results = [];

const primaryKeywords = [
  'intern',
  'internship',
  'job offer',
  'offer letter',
  'shortlisted',
  'stipend',
  'trainee',
  'selected for'
];

for (const item of items) {
  const data = item.json;

  // 1. Extract Subject
  let subject = data.subject || data.Subject || data.title || '';

  // 2. Extract Sender
  let rawFrom = data.from || data.From || data.sender || '';
  let sender = 'Recruiter (via Gmail)';
  if (typeof rawFrom === 'object' && rawFrom !== null) {
    if (rawFrom.text) {
      sender = rawFrom.text.replace(/^["']|["']$/g, '');
    } else if (rawFrom.value && rawFrom.value[0]) {
      const v = rawFrom.value[0];
      sender = v.name ? `${v.name} <${v.address}>` : v.address;
    } else if (rawFrom.address) {
      sender = rawFrom.address;
    } 
  } else if (rawFrom) {
    sender = String(rawFrom).replace(/^["']|["']$/g, '');
  }

  // 3. Extract Full Email Body
  let body = data.text || data.textPlain || data.body;
  if (!body && data.html) {
    body = data.html
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&')
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/\s+/g, ' ')
      .trim();
  }
  if (!body) {
    body = data.snippet || subject;
  }

  // 4. Extract Snippet for preview banner
  let snippet = data.snippet || (body ? body.replace(/\s+/g, ' ').slice(0, 160) : '');

  // 5. Subject fallback if missing
  if (!subject) {
    const subMatch = body.match(/Subject:\s*([^\r\n]+)/i);
    subject = subMatch ? subMatch[1].trim() : 'Internship Offer';
  }

  // 6. Filter keywords
  const fullText = (subject + ' ' + body).toLowerCase();
  const hasPrimaryKeyword = primaryKeywords.some(k => fullText.includes(k));
  const isNewsletter = (fullText.includes('unsubscribe') && !fullText.includes('intern')) ||
                       subject.toLowerCase().startsWith('ppt tips:') ||
                       subject.toLowerCase().includes('newsletter');

  if (hasPrimaryKeyword && !isNewsletter) {
    results.push({
      json: {
        messageId: data.id || data.messageId || '',
        isCandidateOffer: true,
        sender: sender,
        subject: subject,
        snippet: snippet,
        body: body,
        receivedAt: data.date || data.Date || new Date().toISOString()
      }
    });
  }
}

return results;
